head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p.data > M > getAllDataCollection]<br/>화면의 Window 객체에 생성된 모든 DataCollection 의 정보를 반환합니다.",
    "validation" : [
        "type(선택) 파라미터로 반환되는 DataCollection 정보 유형을 설정할 수 있어야 합니다.",
        "type 이 'object' 인 경우 DataCollection 의 객체를 배열로 반환해야 합니다.",
        "type 이 'object' 외의 값(예: 'id', 'string') 인 경우 DataCollection 의 ID 를 문자열 배열로 반환해야 합니다.",
        "type(선택) 을 생략(undefined)하면 기본값으로 DataCollection 의 ID 를 문자열 배열로 반환해야 합니다.",
        "반환되는 DataCollection 정보에는 화면에 정의된 DataList 가 포함되어야 합니다.",
        "반환되는 DataCollection 정보에는 화면에 정의된 DataMap 이 포함되어야 합니다.",
        "type 이 'object' 일 때 반환된 DataCollection 객체에서 getObjectType() 등 객체 메소드를 호출할 수 있어야 합니다.",
        "메소드는 'Page Scope' 가 적용되지 않아 화면의 DataCollection 정보가 모두 반환되어야 합니다.",
        "메소드가 실행된 페이지와 동일한 Window 객체에 생성된 DataCollection 정보가 반환되어야 합니다.",
        "$p.data.create 등으로 동적으로 생성된 DataCollection 도 반환 결과에 포함되어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
    scwin.resetData();
};

// 케이스 실행 전 데이터 초기화 + 동적 생성 DataCollection 정리
scwin.resetData = function () {
    // 화면에 정의된 dataList 초기 데이터
    dlt_exam1.removeAll();
    dlt_exam1.insertRow(0); dlt_exam1.setCellData(0, "code", "C0001"); dlt_exam1.setCellData(0, "label", "TYPE1");
    dlt_exam1.insertRow(1); dlt_exam1.setCellData(1, "code", "C0002"); dlt_exam1.setCellData(1, "label", "TYPE2");
    dlt_exam1.reform();

    dlt_exam2.removeAll();
    dlt_exam2.insertRow(0); dlt_exam2.setCellData(0, "seq", 1); dlt_exam2.setCellData(0, "name", "Alice");
    dlt_exam2.reform();

    dma_exam1.set("lang", "ko");
    dma_exam1.set("output", "WebSquare");
    dma_exam1.reform();

    // 동적 생성된 DataCollection 이 남아 있으면 제거 (시나리오 반복 실행 대비)
    if ($p.getComponentById("dlt_dyn_create")) { $p.data.remove("dlt_dyn_create"); }
    if ($p.getComponentById("dma_dyn_create")) { $p.data.remove("dma_dyn_create"); }
};



scwin.put = function (msg) {
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
};

scwin.verify = function (label, actual, expected) {
    var pass = (String(actual) === String(expected));
    scwin.put("    [" + (pass ? "✓ PASS" : "✗ FAIL") + "] " + label + " = '" + actual + "'" + (pass ? "" : " (기대: '" + expected + "')"));
    return pass;
};

scwin.printResult = function (title, ok) {
    scwin.put(ok ? "결과 : " + title + " 정상 동작 확인" : "결과 : " + title + " 검증 불일치");
    scwin.put("");
};

// 페이지 scope 적용 시 실제 등록 ID 는 "mf_" 또는 "{wfm}_..._w" 접두어가 붙으므로,
// 화면에 정의한 ID 가 끝 부분에 매칭되는지로 비교한다.
scwin.matchId = function (registered, sourceId) {
    var v = String(registered);
    return v === sourceId || v === ("mf_" + sourceId) || v.indexOf("_" + sourceId) === v.length - sourceId.length - 1;
};

// 배열 안에 특정 ID 가 포함되어 있는지 검사
scwin.containsId = function (arr, id) {
    if (!arr || !arr.length) return false;
    for (var i = 0; i < arr.length; i++) {
        if (scwin.matchId(arr[i], id)) return true;
    }
    return false;
};

// 객체 배열 안에 특정 ID 의 객체가 포함되어 있는지 검사 + 해당 객체 반환
scwin.findObjById = function (arr, id) {
    if (!arr || !arr.length) return null;
    for (var i = 0; i < arr.length; i++) {
        if (arr[i] && scwin.matchId(arr[i].id, id)) return arr[i];
    }
    return null;
};



scwin.btn_getAllDataCollection_onclick = function () {
    var s = par_scenario.getValue();

    if (s === "1") {
        scwin.resetData();
        scwin.put("══ 시나리오 1 : type 생략 (기본값 → ID 문자열 배열) ══");
        var arr = $p.data.getAllDataCollection();
        var p1 = scwin.verify("Array.isArray(arr)", Array.isArray(arr), true);
        var p2 = scwin.verify("typeof arr[0] (ID → 'string')", typeof arr[0], "string");
        var p3 = scwin.verify("'dlt_exam1' 포함", scwin.containsId(arr, "dlt_exam1"), true);
        var p4 = scwin.verify("'dlt_exam2' 포함", scwin.containsId(arr, "dlt_exam2"), true);
        var p5 = scwin.verify("'dma_exam1' 포함", scwin.containsId(arr, "dma_exam1"), true);
        scwin.printResult("type 생략 (기본 ID 배열 반환)", p1 && p2 && p3 && p4 && p5);
    } else if (s === "2") {
        scwin.resetData();
        scwin.put("══ 시나리오 2 : type='object' (DataCollection 객체 배열 반환) ══");
        var arr = $p.data.getAllDataCollection("object");
        var p1 = scwin.verify("Array.isArray(arr)", Array.isArray(arr), true);
        var p2 = scwin.verify("typeof arr[0] (객체 → 'object')", typeof arr[0], "object");
        // 객체에 id 프로퍼티가 있어야 함
        var p3 = scwin.verify("arr[0].id 존재 (객체 형태 확인)", arr[0] && arr[0].id ? "true" : "false", "true");
        // dlt_exam1 / dma_exam1 객체 추출
        var oDlt = scwin.findObjById(arr, "dlt_exam1");
        var oDma = scwin.findObjById(arr, "dma_exam1");
        var p4 = scwin.verify("'dlt_exam1' 객체 포함", oDlt ? "true" : "false", "true");
        var p5 = scwin.verify("'dma_exam1' 객체 포함", oDma ? "true" : "false", "true");
        // 객체 메소드 호출 (getObjectType)
        var p6 = scwin.verify("oDlt.getObjectType()", oDlt ? oDlt.getObjectType() : "null", "dataList");
        var p7 = scwin.verify("oDma.getObjectType()", oDma ? oDma.getObjectType() : "null", "dataMap");
        scwin.printResult("type='object' (객체 배열 반환 + 객체 메소드 호출)", p1 && p2 && p3 && p4 && p5 && p6 && p7);
    } else if (s === "3") {
        scwin.resetData();
        scwin.put("══ 시나리오 3 : type='id' (object 외 → ID 문자열 배열 반환) ══");
        var arr = $p.data.getAllDataCollection("id");
        var p1 = scwin.verify("Array.isArray(arr)", Array.isArray(arr), true);
        var p2 = scwin.verify("typeof arr[0]", typeof arr[0], "string");
        var p3 = scwin.verify("'dlt_exam1' 포함", scwin.containsId(arr, "dlt_exam1"), true);
        var p4 = scwin.verify("'dma_exam1' 포함", scwin.containsId(arr, "dma_exam1"), true);
        scwin.printResult("type='id' (object 외 → ID 배열)", p1 && p2 && p3 && p4);
    } else if (s === "4") {
        scwin.resetData();
        scwin.put("══ 시나리오 4 : type='string' (object 외 → ID 문자열 배열 반환) ══");
        var arr = $p.data.getAllDataCollection("string");
        var p1 = scwin.verify("Array.isArray(arr)", Array.isArray(arr), true);
        var p2 = scwin.verify("typeof arr[0]", typeof arr[0], "string");
        var p3 = scwin.verify("'dlt_exam2' 포함", scwin.containsId(arr, "dlt_exam2"), true);
        var p4 = scwin.verify("'dma_exam1' 포함", scwin.containsId(arr, "dma_exam1"), true);
        scwin.printResult("type='string' (object 외 → ID 배열)", p1 && p2 && p3 && p4);
    } else if (s === "5") {
        scwin.resetData();
        scwin.put("══ 시나리오 5 : DataList + DataMap 모두 포함 (Page Scope 미적용 확인) ══");
        var arr = $p.data.getAllDataCollection();
        // 화면에 정의된 모든 DC 가 포함되었는지 (3개 이상)
        var p1 = scwin.verify("arr.length >= 3 (dlt_exam1+dlt_exam2+dma_exam1)", arr.length >= 3 ? "true" : "false", "true");
        var p2 = scwin.verify("DataList 'dlt_exam1' 포함", scwin.containsId(arr, "dlt_exam1"), true);
        var p3 = scwin.verify("DataList 'dlt_exam2' 포함", scwin.containsId(arr, "dlt_exam2"), true);
        var p4 = scwin.verify("DataMap 'dma_exam1' 포함", scwin.containsId(arr, "dma_exam1"), true);
        scwin.printResult("DataList + DataMap 모두 포함 (Page Scope 미적용)", p1 && p2 && p3 && p4);
    } else if (s === "6") {
        scwin.resetData();
        scwin.put("══ 시나리오 6 : 동적 생성 DataCollection 도 결과에 포함 ══");
        // 동적 DataList 생성
        $p.data.create({
            "id" : "dlt_dyn_create", "type" : "dataList",
            "option" : { "baseNode" : "list", "repeatNode" : "map" },
            "columnInfo" : [
                { "id" : "code", "name" : "코드", "dataType" : "text" }
            ]
        });
        // 동적 DataMap 생성
        $p.data.create({
            "id" : "dma_dyn_create", "type" : "dataMap",
            "option" : { "baseNode" : "map" },
            "keyInfo" : [
                { "id" : "k1", "name" : "키1", "dataType" : "text" }
            ]
        });

        var arr = $p.data.getAllDataCollection();
        var p1 = scwin.verify("동적 'dlt_dyn_create' 포함", scwin.containsId(arr, "dlt_dyn_create"), true);
        var p2 = scwin.verify("동적 'dma_dyn_create' 포함", scwin.containsId(arr, "dma_dyn_create"), true);

        // type='object' 로도 확인
        var arrObj = $p.data.getAllDataCollection("object");
        var oDyn = scwin.findObjById(arrObj, "dlt_dyn_create");
        var p3 = scwin.verify("type='object' 결과에 동적 객체 포함", oDyn ? "true" : "false", "true");
        var p4 = scwin.verify("동적 객체 oDyn.getObjectType()", oDyn ? oDyn.getObjectType() : "null", "dataList");

        // 정리
        $p.data.remove("dlt_dyn_create");
        $p.data.remove("dma_dyn_create");
        scwin.printResult("동적 생성 DataCollection 포함 확인", p1 && p2 && p3 && p4);
    }
};
